\pset pager off
with cs as (select v.id vid from terminology.code_systems c join terminology.code_system_versions v on v.code_system_id=c.id where c.internal_code='clinical-pharmacology')
select 'conceptos' k, count(*) from terminology.catalog_concepts where code_system_version_id in (select vid from cs)
union all select 'designaciones', count(*) from terminology.concept_designations d join terminology.catalog_concepts c on c.id=d.concept_id where c.code_system_version_id in (select vid from cs)
union all select 'propiedades', count(*) from terminology.concept_properties p join terminology.catalog_concepts c on c.id=p.concept_id where c.code_system_version_id in (select vid from cs)
union all select 'IS_A', count(*) from terminology.concept_relationships r join terminology.catalog_concepts c on c.id=r.source_concept_id where c.code_system_version_id in (select vid from cs)
union all select 'concept_maps->vademecum', count(*) from terminology.concept_maps m join terminology.catalog_concepts c on c.id=m.source_concept_id where c.code_system_version_id in (select vid from cs)
union all select 'duplicados (code system,code)', count(*) from (select code from terminology.catalog_concepts where code_system_version_id in (select vid from cs) group by code having count(*)>1) x
union all select 'huerfanos: propiedades sin concepto', count(*) from terminology.concept_properties p where p.property_code like 'pharmacology\_%' and not exists (select 1 from terminology.catalog_concepts c where c.id=p.concept_id)
union all select 'huerfanos: IS_A con extremo ausente', count(*) from terminology.concept_relationships r where r.relationship_type_concept_id=(select id from terminology.catalog_concepts where code='terminology:relationship:is-a') and (not exists (select 1 from terminology.catalog_concepts c where c.id=r.source_concept_id) or not exists (select 1 from terminology.catalog_concepts c where c.id=r.target_concept_id))
union all select 'nulos: code/display en conceptos', count(*) from terminology.catalog_concepts where code_system_version_id in (select vid from cs) and (code is null or display is null or code='' or display='')
union all select 'nulos: value_json', count(*) from terminology.concept_properties p join terminology.catalog_concepts c on c.id=p.concept_id where c.code_system_version_id in (select vid from cs) and p.value_json is null
union all select 'secciones sin source/document.id/version-fecha/licencia/url', count(*) from terminology.concept_properties p join terminology.catalog_concepts c on c.id=p.concept_id where c.code_system_version_id in (select vid from cs) and p.property_code like 'pharmacology\_section\_%' and p.property_code <> 'pharmacology_section_coverage' and (p.value_json->>'source' is null or p.value_json#>>'{document,id}' is null or p.value_json#>>'{document,url}' is null or p.value_json->>'license' is null or p.value_json->>'retrievedAt' is null or (p.value_json#>>'{document,version}' is null and p.value_json#>>'{document,revisionDateInText}' is null and p.value_json#>>'{document,effectiveDate}' is null))
union all select 'IS_A ciclos de 1 (auto-referencia)', count(*) from terminology.concept_relationships where source_concept_id=target_concept_id;
select value_json->>'source' fuente, count(*) secciones from terminology.concept_properties where property_code like 'pharmacology\_section\_%' and property_code <> 'pharmacology_section_coverage' group by 1 order by 2 desc;
select (c.code ~ '^[A-Z][0-9]{2}[A-Z]{2}[0-9]{2}$') atc5, count(*) from terminology.catalog_concepts c join terminology.code_system_versions v on v.id=c.code_system_version_id join terminology.code_systems s on s.id=v.code_system_id where s.internal_code='clinical-pharmacology' group by 1;
